import{_ as e,c as r,o as i,af as t}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"22、【賁】 離下艮上","description":"橫渠易說 - 22、【賁】 離下艮上","frontmatter":{"title":"22、【賁】 離下艮上","description":"橫渠易說 - 22、【賁】 離下艮上"},"headers":[],"relativePath":"classics/hengqu/024.md","filePath":"classics/hengqu/024.md"}'),h={name:"classics/hengqu/024.md"};function l(n,a,s,c,d,o){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="_22、【賁】-離下艮上" tabindex="-1">22、【賁】 離下艮上 <a class="header-anchor" href="#_22、【賁】-離下艮上" aria-label="Permalink to “22、【賁】 離下艮上”">​</a></h1><h3 id="彖曰-賁亨-柔來而文剛-故亨。分剛上而文柔-故小利有攸往-天文也-文明以止-人文也。觀乎天文以察時變-觀乎人文以化成天下。" tabindex="-1">彖曰：賁亨，柔來而文剛，故亨。分剛上而文柔，故小利有攸往，天文也；文明以止，人文也。觀乎天文以察時變，觀乎人文以化成天下。 <a class="header-anchor" href="#彖曰-賁亨-柔來而文剛-故亨。分剛上而文柔-故小利有攸往-天文也-文明以止-人文也。觀乎天文以察時變-觀乎人文以化成天下。" aria-label="Permalink to “彖曰：賁亨，柔來而文剛，故亨。分剛上而文柔，故小利有攸往，天文也；文明以止，人文也。觀乎天文以察時變，觀乎人文以化成天下。”">​</a></h3><h3 id="象曰-山下有火-賁-君子以明庶政-無敢折獄。" tabindex="-1">象曰：山下有火，賁，君子以明庶政，無敢折獄。 <a class="header-anchor" href="#象曰-山下有火-賁-君子以明庶政-無敢折獄。" aria-label="Permalink to “象曰：山下有火，賁，君子以明庶政，無敢折獄。”">​</a></h3><p>無敢折獄者，明不兼於下，民未孚也，故止可明政以示民耳。</p><h3 id="初九-賁其趾-舍車而徒。-象曰-舍車而徒-義弗乘也。" tabindex="-1">初九，賁其趾，舍車而徒。 象曰：“舍車而徒”，義弗乘也。 <a class="header-anchor" href="#初九-賁其趾-舍車而徒。-象曰-舍車而徒-義弗乘也。" aria-label="Permalink to “初九，賁其趾，舍車而徒。 象曰：“舍車而徒”，義弗乘也。”">​</a></h3><p>文明之德，以貴居賤，修飾於下，故曰“賁其趾”；義非苟進，故曰“舍車而徒”。六一，賁其須。 象曰：“賁其須”，與上興也。 賁其須，起意在上也。</p><h3 id="九三-賁如濡如-永貞吉。-象曰-永貞之吉-終莫之陵也。" tabindex="-1">九三，賁如濡如，永貞吉。 象曰：永貞之吉，終莫之陵也。 <a class="header-anchor" href="#九三-賁如濡如-永貞吉。-象曰-永貞之吉-終莫之陵也。" aria-label="Permalink to “九三，賁如濡如，永貞吉。 象曰：永貞之吉，終莫之陵也。”">​</a></h3><p>上下皆柔，無物陵犯，然不可邪妄自肆，故永貞然後終保無悔。</p><h3 id="六四-賁如皤如-白馬翰如-匪寇婚媾。-象曰-六四當位-疑也。-匪寇婚媾-終無尤也。" tabindex="-1">六四，賁如皤如，白馬翰如，匪寇婚媾。 象曰：六四當位，疑也。“匪寇婚媾”，終無尤也。 <a class="header-anchor" href="#六四-賁如皤如-白馬翰如-匪寇婚媾。-象曰-六四當位-疑也。-匪寇婚媾-終無尤也。" aria-label="Permalink to “六四，賁如皤如，白馬翰如，匪寇婚媾。 象曰：六四當位，疑也。“匪寇婚媾”，終無尤也。”">​</a></h3><p>以陰居陰，性為艮止，故志堅行潔，終無尤累。</p><h3 id="六五-賁於丘園-束帛戔戔-吝終吉。-象曰-六五之吉-有喜也。" tabindex="-1">六五，賁於丘園，束帛戔戔，吝終吉。 象曰：六五之吉，有喜也。 <a class="header-anchor" href="#六五-賁於丘園-束帛戔戔-吝終吉。-象曰-六五之吉-有喜也。" aria-label="Permalink to “六五，賁於丘園，束帛戔戔，吝終吉。 象曰：六五之吉，有喜也。”">​</a></h3><p>陰陽相固，物所阜生，柔中之德比於上九。上九敦素，因可恃而致富，雖為悔吝，然獲其吉也。 其道上行，故曰“丘園”。悔一作隘。</p><h3 id="上九-白賁-無咎。-象曰-白賁無咎-上得志也。" tabindex="-1">上九，白賁，無咎。 象曰：“白賁無咎”，上得志也。 <a class="header-anchor" href="#上九-白賁-無咎。-象曰-白賁無咎-上得志也。" aria-label="Permalink to “上九，白賁，無咎。 象曰：“白賁無咎”，上得志也。”">​</a></h3><p>上而居高，潔無所累，為物所貴，故曰“上得志也”。上一作止。</p>',14)])])}const f=e(h,[["render",l]]);export{_ as __pageData,f as default};
